private static ParameterizedType findGenericSuperclass(Class<?> target, Class<?> raw) {
    // Check target's genericSuperclass
    Type gSuper = target.getGenericSuperclass();
    if (gSuper instanceof ParameterizedType) {
        ParameterizedType pSuper = (ParameterizedType) gSuper;
        Type rawSuper = pSuper.getRawType();
        if (rawSuper instanceof Class) {
            if (((Class<?>)rawSuper).equals(raw)) {
                return pSuper;
            } else {
                // Recursively search in that supertype's raw class.
                Class<?> rawSuperClass = (Class<?>)rawSuper;
                ParameterizedType result = findGenericSuperclass(rawSuperClass, raw);
                if (result != null) return result;
            }
        }
    } else if (gSuper instanceof Class) {
        // Not parameterized, recursively search
        Class<?> superClass = (Class<?>) gSuper;
        if (superClass != null) {
            if (superClass.equals(raw)) return null; // no param
            ParameterizedType result = findGenericSuperclass(superClass, raw);
            if (result != null) return result;
        }
    }
    // Check interfaces
    for (Type iface : target.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType pIface = (ParameterizedType) iface;
            Type rawIface = pIface.getRawType();
            if (rawIface instanceof Class && ((Class<?>)rawIface).equals(raw)) {
                return pIface;
            } else if (rawIface instanceof Class) {
                ParameterizedType res = findGenericSuperclass(((Class<?>)rawIface), raw);
                if (res != null) return res;
            }
        } else if (iface instanceof Class) {
            Class<?> ifaceClass = (Class<?>) iface;
            if (ifaceClass.equals(raw)) return null;
            ParameterizedType res = findGenericSuperclass(ifaceClass, raw);
            if (res != null) return res;
        }
    }
    // not found
    return null;
}

