        Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
        Set<V> larger = set1.size() <= set2.size() ? set2 : set1;
        for (V elem : smaller) {
            if (larger.contains(elem)) {
                result.add(elem);
            }
        }
        return result;
    } catch (Exception e) {
        return new HashSet<>();
    }
}

